import React from 'react';
import { BrowserRouter, Routes, Route } from 'react-router-dom';
import MainLayout from './layout/MainLayout';
import MainBoardPage from './pages/mainboard/MainBoardPage';

// 알림 관련 페이지
import NotificationsPage from './pages/notifications/NotificationsPage';
import NotificationDetailPage from './pages/notifications/NotificationDetailPage';
import NotificationStatsPage from './pages/notifications/NotificationStatsPage';

// 로그 페이지
import LogsPage from './pages/logs/LogsPage';

// 설정 관련 페이지
import SettingsHomePage from './pages/settings/SettingsHomePage';
import SettingsFoldersPage from './pages/settings/SettingsFoldersPage';
import SettingsNotifyPage from './pages/settings/SettingsNotifyPage';

import SettingsExceptionsPage from './pages/settings/SettingsExceptionsPage';
import SettingsResetPage from './pages/settings/SettingsResetPage';
import SettingsUpdatePage from './pages/settings/SettingsUpdatePage';
import SettingsFeedbackPage from './pages/settings/SettingsFeedbackPage';

function App() {
  return (
    <BrowserRouter>
      <MainLayout>
        <Routes>
          {/* 메인 보드 */}
          <Route path="/" element={<MainBoardPage />} />

          {/* 알림 */}
          <Route path="/notifications" element={<NotificationsPage />} />
          <Route path="/notifications/stats" element={<NotificationStatsPage />} />
          <Route path="/notifications/:id" element={<NotificationDetailPage />} />

          {/* 로그 */}
          <Route path="/logs" element={<LogsPage />} />

          {/* 설정 */}
          <Route path="/settings" element={<SettingsHomePage />} />
          <Route path="/settings/folders" element={<SettingsFoldersPage />} />
          <Route path="/settings/exceptions" element={<SettingsExceptionsPage />} />
          <Route path="/settings/notify" element={<SettingsNotifyPage />} />
          <Route path="/settings/reset" element={<SettingsResetPage />} />
          <Route path="/settings/update" element={<SettingsUpdatePage />} />
          <Route path="/settings/feedback" element={<SettingsFeedbackPage />} />
        </Routes>
      </MainLayout>
    </BrowserRouter>
  );
}

export default App;
